#include <iostream>
#include <cmath>
#include <iomanip>

int main() {
    const double x = 13.657;
    const double y = 2.333;
    const double zero_rad = 0.0;

    std::cout << std::fixed << std::setprecision(3);
    std::cout << "fmod: " << std::fmod(x, y) << "\n";
    std::cout << "sin: " << std::sin(zero_rad) << "\n";
    std::cout << "cos: " << std::cos(zero_rad) << "\n";
    std::cout << "tan: " << std::tan(zero_rad) << "\n";

    return 0;
}

#include <iostream>

// Function prototype
int square(int y);

int main() {
    for (int x = 1; x <= 10; ++x) {
        std::cout << square(x) << ((x == 10) ? "" : "  ");
    }
    std::cout << "\n";
    // Implicit return 0 in modern C++
}

// Function definition
int square(int y) {
    return y * y;
}
